window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[171]={"id":"171","numero":171,"titre":"Gale & Pédiculoses","objectifs":[{"id":"171-1","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les modes de transmission principaux et l’épidémiologie de la gale et des pédiculoses","contenu":"<p>La <span class=\"kw-etio\">gale</span> est une <span class=\"kw-def\">ectoparasitose humaine</span>\n      responsable d'une dermatose fréquente, <strong>endémo-épidémique mondiale en recrudescence</strong>.\n      L'<strong>homme est le seul réservoir</strong>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">pédiculoses</span> sont des\n      ectoparasitoses <strong>strictement humaines et ubiquitaires</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Transmission directe</th><th>Transmission indirecte</th><th><span class=\"kw-def\">Terrain</span> / contexte</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Gale</span></strong></td>\n            <td><span class=\"kw-clinique\">Interhumaine ++</span> : 1 <span class=\"kw-def\">contact</span> suffit ; contacts intimes et prolongés (familial, couple)</td>\n            <td><span class=\"kw-clinique\">Rare</span> (linge, literie) — sauf formes <span class=\"kw-alerte\">profuses</span> et <span class=\"kw-alerte\">hyperkératosiques</span></td>\n            <td>Collectivités médicalisées, foyers de personnes âgées, milieux défavorisés, immunodéprimés ; <span class=\"kw-etio\">gale</span> du <strong>pubis = <span class=\"kw-clinique\">IST</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pédiculose du cuir chevelu</strong></td>\n            <td><span class=\"kw-clinique\">Interhumaine ++</span> (<span class=\"kw-def\">contact</span> des têtes)</td>\n            <td>Possible (bonnets, peignes, brosses)</td>\n            <td><strong>Collectivités d'enfants</strong> en milieu scolaire — <strong>tous <span class=\"kw-clinique\">les</span> milieux sociaux</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pédiculose corporelle</strong></td>\n            <td><span class=\"kw-clinique\">Interhumaine</span></td>\n            <td><span class=\"kw-clinique\">++</span> (vêtements)</td>\n            <td><span class=\"kw-alerte\">Marqueur de précarité</span> : camps de réfugiés, prisons, SDF (manque d'hygiène + froid)</td>\n          </tr>\n          <tr>\n            <td><strong>Phtiriase pubienne</strong></td>\n            <td><span class=\"kw-clinique\">Sexuelle</span></td>\n            <td>—</td>\n            <td><strong><span class=\"kw-clinique\">IST</span></strong> — penser au <span class=\"kw-def\">dépistage</span> des autres IST</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span> · 59 — Sujet en situation de précarité</em></p>","frequence":0},{"id":"171-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la gale","contenu":"<p>Agent : <span class=\"kw-etio\">Sarcoptes scabiei var. hominis</span>, un <strong>acarien</strong>.\n      Ce sont <span class=\"kw-clinique\">les</span> <strong>femelles</strong> qui sont responsables de la maladie.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Mobilité</td><td>Déplacement de <span class=\"kw-chiffre\">plusieurs cm/h</span> à la surface de la peau ; bonne mobilité à <span class=\"kw-chiffre\">25-30 °C</span>, perte de mobilité <span class=\"kw-chiffre\">&lt; 20 °C</span></td></tr>\n          <tr><td>Destruction thermique</td><td>Tué par une température de <span class=\"kw-chiffre\">55 °C</span> ; meurt en <span class=\"kw-chiffre\">12 à 24 h</span> hors de l'hôte</td></tr>\n          <tr><td>Incubation</td><td><span class=\"kw-chiffre\">≈ 3 semaines</span> — plus courte si réinfestation (<span class=\"kw-chiffre\">5 j à 1 mois</span>)</td></tr>\n          <tr><td>Cycle <span class=\"kw-etio\">parasitaire</span></td><td><span class=\"kw-chiffre\">≈ 20 jours</span></td></tr>\n          <tr><td>Charge <span class=\"kw-etio\">parasitaire</span></td><td><span class=\"kw-chiffre\">10-20 femelles</span> par individu (<span class=\"kw-etio\">gale</span> commune)</td></tr>\n        </tbody>\n      </table>\n      <p>Le mécanisme se déroule en trois temps :</p>\n      <ul>\n        <li>La <strong>femelle</strong> creuse un <span class=\"kw-clinique\">tunnel (sillon)</span> dans la <span class=\"kw-def\">couche cornée</span> de l'épiderme et y <strong>pond ses œufs</strong>.</li>\n        <li>La <span class=\"kw-def\">réaction urticarienne</span> de l'hôte est responsable du <strong><span class=\"kw-clinique\">prurit</span></strong>.</li>\n        <li>Le grattage expose au risque de <span class=\"kw-alerte\">surinfection bactérienne</span>.</li>\n      </ul>","frequence":0},{"id":"171-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les différents agents des pédiculoses","contenu":"<p><span class=\"kw-clinique\">Les</span> pédiculoses sont dues à des <span class=\"kw-etio\">poux</span> : <strong><span class=\"kw-def\">insectes hématophages</span></strong>,\n      parasites stricts de l'homme, qui ne viennent sur la peau que pour se nourrir. Leur <strong>piqûre</strong>\n      et leurs <strong>déjections</strong> sont prurigineuses. On distingue trois espèces :</p>\n      <table >\n        <thead><tr><th>Espèce</th><th>Nom courant</th><th>Localisation / mobilité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Pediculus humanus capitis</span></td><td>Pou de tête</td><td>Cuir chevelu — <strong>très mobile</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">Pediculus humanus corporis</span></td><td>Pou de corps</td><td>Corps ; se réfugie dans <span class=\"kw-clinique\">les</span> vêtements — <strong>très mobile</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">Phtirus pubis</span> (Phtirius inguinalis)</td><td>Pou du pubis / <span class=\"kw-etio\">morpion</span></td><td>Région génitale — <strong>vit accroché aux poils</strong> (immobile)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/171/poux-comparatif.png\" alt=\"Schéma comparatif des trois poux humains : pou de tête, pou de corps allongé, pou du pubis trapu en forme de crabe\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Les</span> trois poux humains : le pou de tête et le pou de corps ont un corps allongé, le pou du pubis a un corps trapu et ramassé (« en crabe »). Source : fiche source EDN item 171 (Collège de dermatologie).</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":0},{"id":"171-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes évocateurs de gale et de pédiculoses","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-etio\">Gale</span> — forme typique</h4>\n      <p>Le maître symptôme est un <strong><span class=\"kw-clinique\">prurit</span> diffus à recrudescence nocturne</strong>,\n      qui <strong>épargne le visage</strong> et a souvent un <strong>caractère conjugal ou familial</strong>.\n      Penser à la <span class=\"kw-etio\">gale</span> devant tout <span class=\"kw-clinique\">prurit</span> : certaines formes sont pauci-lésionnelles.</p>\n      <p><strong>Lésions non spécifiques</strong> (de grattage), de topographie évocatrice :\n      <span class=\"kw-clinique\">espaces interdigitaux</span>, face antérieure des poignets et des avant-bras, coudes,\n      <span class=\"kw-clinique\">aisselles</span>, région <span class=\"kw-clinique\">ombilicale</span>, fesses et face interne\n      des cuisses ; <span class=\"kw-clinique\">mamelon/aréole</span> chez la femme,\n      <span class=\"kw-clinique\">OGE (verge)</span> chez l'homme.</p>\n      <p><strong>Lésions spécifiques</strong> de la <span class=\"kw-etio\">gale</span> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Topographie</th><th>Lésion élémentaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Sillon scabieux</span></strong></td><td>Espaces interdigitaux ; face antérieure des poignets</td><td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-clinique\">sinueuse</span> de quelques mm = trajet de l'acarien femelle dans la couche cornée, contenant <span class=\"kw-clinique\">les</span> œufs ; <span class=\"kw-clinique\">éminence acarienne</span> à une extrémité (position du parasite)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vésicule</span> perlée</strong></td><td>Espaces interdigitaux</td><td>Petite <span class=\"kw-clinique\">élevure translucide</span> reposant sur une base érythémateuse</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Nodule</span> scabieux</strong></td><td>Régions génitales de l'homme</td><td><span class=\"kw-clinique\">Papulo-nodule</span> rouge ou violacé, prurigineux, parfois excorié</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculoses — signes évocateurs</h4>\n      <table >\n        <thead><tr><th>Pédiculose</th><th><span class=\"kw-clinique\">Prurit</span> / lésions</th><th>Diagnostic de certitude</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cuir chevelu</strong></td><td><span class=\"kw-clinique\">Prurit du cuir chevelu</span> diurne et nocturne, diffus ou à prédominance <span class=\"kw-clinique\">rétro-auriculaire</span>, extension à la nuque ; lésions de grattage ; <span class=\"kw-alerte\">impétiginisation du cou</span> + <span class=\"kw-clinique\">adénopathies</span> occipitales</td><td><span class=\"kw-clinique\">Poux vivants</span> (bruns, allongés, très mobiles) ; <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">lentes vivantes</span> orientent (œufs collés au cheveu, ne coulissant pas, rétro-auriculaires)</td></tr>\n          <tr><td><strong>Corporelle</strong></td><td><span class=\"kw-clinique\">Prurit intense</span> ; excoriations + <span class=\"kw-clinique\">éruption</span> maculo-papuleuse prédominant au dos, au thorax et à la racine des membres ; <span class=\"kw-clinique\">leucomélanodermie</span> si infestation chronique</td><td>Poux et lentes surtout sur <span class=\"kw-clinique\">les</span> <strong>vêtements (coutures)</strong></td></tr>\n          <tr><td><strong>Phtiriase pubienne</strong></td><td><span class=\"kw-clinique\">Prurit pubien</span> + lésions de grattage du pubis et de l'hypogastre</td><td><span class=\"kw-clinique\">Lentes</span> grisâtres et <span class=\"kw-clinique\">poux immobiles</span> à la base des poils</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Penser à la <strong><span class=\"kw-etio\">gale</span></strong> devant tout <span class=\"kw-clinique\">prurit</span>.\n      Tout <strong><span class=\"kw-clinique\">impétigo</span> de l'adulte</strong> doit faire rechercher une gale ; tout impétigo de la\n      <strong>nuque ou du cuir chevelu</strong> doit faire rechercher une pédiculose.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 116 — <span class=\"kw-clinique\">Prurit</span> · 155 — Infection cutanéo-muqueuse</em></p>","frequence":3},{"id":"171-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes atypiques de gale et de pédiculoses","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-etio\">Gale</span> — formes cliniques particulières</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Gale</span> du nourrisson</strong></td><td><strong>Atteinte possible du visage</strong> ; <span class=\"kw-clinique\">vésico-pustules palmo-plantaires</span> ; <strong>nodules scabieux péri-axillaires</strong> (et non génitaux comme chez l'adulte)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Gale</span> profuse</strong></td><td><span class=\"kw-clinique\">Éruption</span> profuse et étendue, <strong>y compris le dos</strong> ; <span class=\"kw-def\">terrain</span> : personne âgée alitée, troubles des fonctions supérieures<br>Causes : diagnostic tardif ; déficit immunitaire (<span class=\"kw-etio\">VIH</span> ++) ; traitement inadapté (<span class=\"kw-ci\">corticothérapie</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Gale</span> hyperkératosique</strong></td><td><span class=\"kw-def\">Terrain</span> : immunodéprimés ou sujets âgés sous <span class=\"kw-ttt\">immunosuppresseurs</span> (<span class=\"kw-ci\">corticothérapie</span>) ; <span class=\"kw-alerte\">contagiosité majeure</span> (prolifération <span class=\"kw-etio\">parasitaire</span> intense) ; <span class=\"kw-clinique\">prurit</span> discret voire absent ; atteinte de tout le corps y compris visage, cuir chevelu et <strong>ongles</strong>, voire <span class=\"kw-alerte\">érythrodermie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes compliquées</strong> : <span class=\"kw-alerte\">impétiginisation</span> (cause majeure de\n      <span class=\"kw-alerte\">RAA</span> et de <span class=\"kw-alerte\">glomérulonéphrite post-streptococcique</span>\n      dans <span class=\"kw-clinique\">les</span> pays en développement) ; eczématisation (secondaire à la <span class=\"kw-etio\">gale</span> ou à son traitement).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Nodules scabieux <span class=\"kw-bio\">vs</span> post-scabieux (à distinguer)</h4>\n      <table >\n        <thead><tr><th></th><th>Nodules scabieux</th><th>Nodules post-scabieux</th></tr></thead>\n        <tbody>\n          <tr><td>Siège</td><td>Régions génitales</td><td>Ubiquitaire</td></tr>\n          <tr><td>Aspect</td><td>Papulo-nodules rouges/violets</td><td>Papulo-nodules rouges/cuivrés</td></tr>\n          <tr><td>Sarcopte</td><td><strong>En contiennent</strong></td><td><strong>N'en contiennent pas</strong> — réaction immuno-<span class=\"kw-etio\">allergique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td>Régressent avec le traitement</td><td><span class=\"kw-alerte\">Persistent plusieurs semaines après un traitement efficace</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> <span class=\"kw-clinique\">Les</span> <strong>nodules post-scabieux</strong>\n      qui persistent après traitement ne contiennent pas de sarcopte et <span class=\"kw-alerte\">ne justifient pas\n      un retraitement</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculose corporelle — infections transmises par le pou de corps</h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Fièvre</span> récurrente cosmopolite</strong> — <span class=\"kw-etio\">Borrelia recurrentis</span>.</li>\n        <li><strong>Typhus exanthématique (épidémique)</strong> — <span class=\"kw-etio\">Rickettsia prowazekii</span> (à ne pas confondre avec la <span class=\"kw-clinique\">fièvre</span> typhoïde).</li>\n        <li><strong><span class=\"kw-clinique\">Fièvre</span> des tranchées</strong> — <span class=\"kw-etio\">Bartonella quintana</span> : recrudescence chez <span class=\"kw-clinique\">les</span> sujets précaires et <span class=\"kw-etio\">alcooliques</span> des métropoles ; responsable de <span class=\"kw-alerte\">septicémie</span> et d'<span class=\"kw-alerte\">endocardite</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 152 — <span class=\"kw-def\">Endocardite</span> infectieuse · 261 — Néphropathie glomérulaire</em></p>","frequence":0},{"id":"171-6","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie de lésions de gale","contenu":"<p>La sémiologie de la <span class=\"kw-etio\">gale</span> se résume en quatre lésions, photographiées sur cette planche de référence :</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/171/gale-lesions-planche.png\" alt=\"Planche de 4 photographies de lésions de gale : sillon scabieux des espaces interdigitaux, vésicules perlées de l'avant-bras, nodules scabieux de la verge, gale hyperkératosique\" loading=\"lazy\">\n        <figcaption>Quatre lésions de gale : sillon interdigital, vésicules perlées, nodules scabieux de la verge, gale hyperkératosique. Source : fiche source EDN item 171 (Pilly / Collège de dermatologie).</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Code</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Sillon scabieux</span></strong></td><td>P-171-1</td><td><span class=\"kw-clinique\">lésion</span> <span class=\"kw-clinique\">sinueuse</span> de quelques millimètres dans un <span class=\"kw-clinique\">espace interdigital</span> : trajet de l'acarien femelle.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vésicules perlées</span></strong></td><td>P-171-2</td><td>petites <span class=\"kw-clinique\">élevures translucides</span> sur base érythémateuse, ici à l'avant-bras.</td></tr>\n          <tr><td><strong>Nodules scabieux</strong></td><td>P-171-3</td><td><span class=\"kw-clinique\">papulo-nodules</span> rouges de la <span class=\"kw-clinique\">verge</span>, de <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">5-10 mm</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Gale</span> hyperkératosique</strong></td><td>P-171-4</td><td><span class=\"kw-alerte\">placards érythémato-squameux étendus</span> : contagiosité majeure.</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"171-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une pédiculose du cuir chevelu","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/171/pediculose-cuir-chevelu-lentes.png\" alt=\"Photographie de cuir chevelu : lentes blanc-grisâtres collées à la base des cheveux au cours d'une pédiculose du cuir chevelu\" loading=\"lazy\">\n        <figcaption>Pédiculose du cuir chevelu : lentes (œufs) blanc-grisâtres collées à la t<span class=\"kw-chiffre\">ige</span> pilaire. Source : fiche source EDN item 171 (Collège de dermatologie).</figcaption>\n      </figure>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Lentes</span></strong> — œufs blanc-grisâtres <strong>collés à la t<span class=\"kw-chiffre\">ige</span> pilaire</strong>, qui <span class=\"kw-clinique\">ne coulissent pas</span> le long du cheveu (à la différence des <span class=\"kw-etio\">pellicules</span>) ; prédominance <span class=\"kw-clinique\">rétro-auriculaire</span>.</li>\n        <li>Une lente située <span class=\"kw-chiffre\">&gt; 1 cm</span> de l'émergence du cheveu est <strong>non viable</strong> (cheveu déjà poussé).</li>\n        <li><strong>Poux</strong> adultes — bruns, allongés, mobiles ; la découverte de <span class=\"kw-clinique\">poux vivants</span> fait le <strong>diagnostic de certitude</strong>.</li>\n      </ul>","frequence":0},{"id":"171-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","contenu":"<p>La <strong><span class=\"kw-etio\">gale du pubis</span></strong> et la <strong><span class=\"kw-etio\">phtiriase pubienne</span></strong> correspondent à des\n      <span class=\"kw-etio\">infections sexuellement transmissibles (IST)</span>.</p>\n      <p>Conduite à tenir devant l'une de ces atteintes — ou devant une <span class=\"kw-etio\">gale</span> survenue dans un contexte de\n      <strong>rapports sexuels à risque</strong> :</p>\n      <ul>\n        <li><strong>Rechercher systématiquement <span class=\"kw-clinique\">les</span> autres <span class=\"kw-clinique\">IST</span></strong> : prescrire un <span class=\"kw-bio\">bilan d'IST</span>.</li>\n        <li><strong>Dépister et traiter <span class=\"kw-clinique\">les</span> partenaires sexuels</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Il n'existe <strong>pas de signe <span class=\"kw-ttt\">biologique</span>\n      spécifique</strong> de la <span class=\"kw-etio\">gale</span> elle-même : le bilan biologique demandé est celui des\n      <strong><span class=\"kw-clinique\">IST</span> associées</strong>, pas un bilan « de gale ».</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":0},{"id":"171-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications du diagnostic parasitologique","contenu":"<p>Le diagnostic de <span class=\"kw-etio\">gale</span> est <strong>avant tout clinique</strong> (anamnèse + topographie évocatrice) ;\n      l'<span class=\"kw-bio\">examen parasitologique</span> n'est <strong>pas obl<span class=\"kw-chiffre\">iga</span>toire</strong> pour le poser.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen parasitologique direct — technique</h4>\n      <ul>\n        <li>Gratter un <span class=\"kw-clinique\">sillon</span> au <strong>vaccinostyle</strong>, en prélevant si possible l'<span class=\"kw-clinique\">éminence acarienne</span>.</li>\n        <li>Observation au <strong>microscope</strong> : met en évidence <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">œufs</span> ou l'<span class=\"kw-bio\">acarien femelle adulte</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications</h4>\n      <ul>\n        <li>Confirmation en cas de <strong>doute diagnostique</strong> ou de forme atypique.</li>\n        <li><strong>Négativation</strong> exigée avant de lever l'éviction des gales <span class=\"kw-alerte\">profuses</span> et <span class=\"kw-alerte\">hyperkératosiques</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Limite.</strong> La mise en évidence du parasite est\n      <span class=\"kw-alerte\">difficile en dehors des formes profuses et hyperkératosiques</span> : un examen\n      négatif n'élimine pas une <span class=\"kw-etio\">gale</span> commune.</div>","frequence":0},{"id":"171-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’intérêt du dermatoscope pour le diagnostic de gale","contenu":"<p>La <span class=\"kw-imagerie\">dermatoscopie</span> est un examen simple et non invasif, réalisable au cabinet.</p>\n      <ul>\n        <li>Elle montre un aspect caractéristique <strong>« en <span class=\"kw-radio\">deltaplane</span> »</strong> : la tête de l'acarien femelle visible à l'extrémité du <span class=\"kw-clinique\">sillon</span>.</li>\n        <li>Elle permet de <strong>remplacer l'<span class=\"kw-bio\">examen parasitologique</span></strong>, peu accessible en pratique de ville.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le diagnostic de <span class=\"kw-etio\">gale</span> reste <strong>avant tout\n      clinique</strong> : ni la dermatoscopie ni l'<span class=\"kw-bio\">examen parasitologique</span> ne sont obl<span class=\"kw-chiffre\">iga</span>toires pour le poser.</div>","frequence":0},{"id":"171-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d’une gale et d’une pédiculose","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-etio\">Gale</span> — principes</h4>\n      <table >\n        <thead><tr><th></th><th>Traitement général</th><th>Traitements locaux</th></tr></thead>\n        <tbody>\n          <tr><td>Molécule</td><td><span class=\"kw-ttt\">Ivermectine</span> per os</td><td><span class=\"kw-ttt\">Benzoate de benzyle</span> ; <span class=\"kw-ttt\">perméthrine</span></td></tr>\n          <tr><td>Intention</td><td><strong>1ʳᵉ intention</strong></td><td>Alternative / 2ᵉ intention</td></tr>\n          <tr><td>Schéma</td><td>Prise unique, <strong>à répéter à <span class=\"kw-chiffre\">7-14 jours</span></strong> (cycle <span class=\"kw-etio\">parasitaire</span>)</td><td>2 applications espacées (voir ci-dessous)</td></tr>\n          <tr><td>Âge / <span class=\"kw-def\">terrain</span></td><td>AMM si <strong><span class=\"kw-chiffre\">&gt; 2 ans ET &gt; 15 kg</span></strong> — <span class=\"kw-ci\">CI &lt; 2 ans ou &lt; 15 kg</span></td><td>Possibles chez la <strong>femme enceinte</strong>, hors <span class=\"kw-ci\">allaitement</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-etio\">Gale</span> — traitements locaux en détail</h4>\n      <table >\n        <thead><tr><th></th><th>Benzoate de benzyle</th><th>Perméthrine</th></tr></thead>\n        <tbody>\n          <tr><td>Galénique</td><td>Émulsion cutanée <span class=\"kw-chiffre\">10 %</span></td><td>Crème <span class=\"kw-chiffre\">5 %</span></td></tr>\n          <tr><td>Âge minimal</td><td>Dès <span class=\"kw-chiffre\">1 mois</span> — <span class=\"kw-ci\">CI &lt; 1 mois</span> (toxicité neurologique)</td><td>Dès <span class=\"kw-chiffre\">2 mois</span></td></tr>\n          <tr><td>Zone d'application</td><td>Du <strong>cuir chevelu aux orteils</strong></td><td>Du <strong>cou aux orteils</strong></td></tr>\n          <tr><td>Schéma</td><td>2 applications à <span class=\"kw-chiffre\">8 jours</span> d'intervalle</td><td>2 applications à <span class=\"kw-chiffre\">7 jours</span> d'intervalle</td></tr>\n          <tr><td>Temps de pose</td><td><span class=\"kw-chiffre\">24 h</span> chez l'adulte ; <span class=\"kw-chiffre\">6-12 h</span> entre <span class=\"kw-chiffre\">1 mois</span> et <span class=\"kw-chiffre\">2 ans</span></td><td><span class=\"kw-chiffre\">8-12 h</span></td></tr>\n        </tbody>\n      </table>\n      <p>Modalités d'application : après une douche tiède au savon, sur tout le corps zones génitales comprises,\n      puis sous-vêtements propres ; <strong>ne pas se laver pendant la pose</strong> ; au retrait, douche\n      à l'eau et au savon puis <span class=\"kw-ttt\">émollient</span>.</p>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-etio\">Gale</span> profuse / hyperkératosique.</strong> Associer le traitement\n      local <strong>+</strong> l'ivermectine PO ; <strong><span class=\"kw-def\">isolement</span></strong> du malade (précautions de type\n      <span class=\"kw-def\">contact</span>), idéalement en <span class=\"kw-alerte\">hospitalisation</span>.</div>\n      <p><strong>Environnement</strong> : linge et literie lavés à <span class=\"kw-chiffre\">&gt; 60 °C</span> en machine\n      (cycle long) <strong>ou</strong> enfermés dans un sac plastique <span class=\"kw-chiffre\">72 h</span> ;\n      désinfection des lieux de vie si <span class=\"kw-etio\">gale</span> profuse.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculoses — traitement</h4>\n      <p>Traitement <strong>local</strong> par <span class=\"kw-ttt\">diméticone</span> ou oxyphthirine\n      (destruction <strong>mécanique</strong> du pou ; le malathion et la perméthrine ne sont plus disponibles).\n      Un <strong>2ᵉ traitement à <span class=\"kw-chiffre\">7-10 jours</span></strong> est systématique (mauvais effet\n      lenticide). <span class=\"kw-clinique\">Les</span> solutions, lotions et crèmes sont préférées aux shampooings et poudres.</p>\n      <table >\n        <thead><tr><th>Pédiculose</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cuir chevelu</strong></td><td><span class=\"kw-ttt\">Diméticone</span> en solution/lotion, <strong>raie par raie</strong>, pose de <span class=\"kw-chiffre\">15 min</span> à<span class=\"kw-chiffre\"> 1 h</span>, puis shampooing doux + rinçage + peignage ; <strong>pas de traitement présomptif</strong> (seules <span class=\"kw-clinique\">les</span> pédiculoses actives se traitent)<br>Échec d'un traitement local bien conduit : <span class=\"kw-ttt\">ivermectine</span> PO (<span class=\"kw-alerte\">hors AMM</span> ; &gt;<span class=\"kw-chiffre\"> 2 ans</span> et &gt;<span class=\"kw-chiffre\"> 15 kg</span> ; répétée à 7 j)</td></tr>\n          <tr><td><strong>Corporelle</strong></td><td>Hygiène corporelle, douche au savon, <strong>changement de vêtements</strong> ; linge lavé à <span class=\"kw-chiffre\">60 °C</span> ou enfermé en sac plastique <span class=\"kw-chiffre\">7 jours</span></td></tr>\n          <tr><td><strong>Phtiriase pubienne</strong></td><td><span class=\"kw-ttt\">Perméthrine</span> topique, renouvelée à <span class=\"kw-chiffre\">7 jours</span> ; le <strong>rasage</strong> est le meilleur traitement ; rechercher <span class=\"kw-clinique\">les</span> autres <span class=\"kw-clinique\">IST</span> et traiter les partenaires</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":2},{"id":"171-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","contenu":"<p>Le traitement des contacts est <strong>simultané</strong> à celui du cas index.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Qui traiter</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">contacts proches</span></strong> : personnes <strong>vivant sous le même toit</strong> et <strong>partenaires sexuels</strong>.</li>\n        <li><strong>Même s'ils sont asymptomatiques.</strong></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Comment</h4>\n      <ul>\n        <li><strong>Même traitement</strong> que le cas index : soit un <span class=\"kw-ttt\">traitement local</span> (peut suffire), soit l'<span class=\"kw-ttt\">ivermectine</span> PO — à privilégier pour l'observance quand le nombre de personnes à traiter est important.</li>\n        <li>Traiter <strong>en même temps</strong> le linge et l'environnement.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne pas attendre que <span class=\"kw-clinique\">les</span> contacts\n      deviennent symptomatiques : le traitement est <strong>simultané et systématique</strong>, sinon\n      recontamination du cas index.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":0},{"id":"171-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les causes d’échec du traitement de la gale et des pédiculoses","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-etio\">Gale</span> — <span class=\"kw-clinique\">prurit</span> persistant <span class=\"kw-chiffre\">8-15 jours</span> après le traitement</h4>\n      <p>Un <span class=\"kw-clinique\">prurit</span> qui persiste n'est pas toujours un échec. Évoquer :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Eczéma de contact</span> ; <span class=\"kw-etio\">irritation par le traitement</span>.</li>\n        <li><span class=\"kw-etio\">Parasitophobie</span> ; autres causes de <span class=\"kw-clinique\">prurit</span>.</li>\n        <li><strong>Nodules post-scabieux</strong> persistants — réaction immuno-<span class=\"kw-etio\">allergique</span>, qui <span class=\"kw-alerte\">ne justifient pas un retraitement</span>.</li>\n      </ul>\n      <p><strong>Échec vrai</strong> (lésions cliniques évocatrices et/ou <span class=\"kw-bio\">examen parasitologique</span> positif) :\n      <span class=\"kw-etio\">rechute</span> après un traitement inapproprié ; rechute liée à une\n      <span class=\"kw-alerte\">résistance</span> au traitement ; <span class=\"kw-etio\">recontamination</span>\n      après guérison.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculoses — causes d'échec</h4>\n      <ul>\n        <li>Incompréhension, ignorance, négligence ; <span class=\"kw-etio\">coût</span> (aucune spécialité n'est remboursée).</li>\n        <li><span class=\"kw-etio\">Réinfestation</span> à partir de l'environnement.</li>\n        <li>Durée ou fréquence d'utilisation insuffisantes ; <span class=\"kw-etio\">quantité de produit insuffisante</span> ; forme galénique inappropriée.</li>\n        <li><span class=\"kw-alerte\">Acquisition de résistance</span> des poux.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Pédiculose du cuir chevelu — examen de contrôle.</strong> Poux vivants\n      à <span class=\"kw-chiffre\">J2</span> → <span class=\"kw-alerte\">résistance</span> probable → <strong>changer de\n      classe</strong> pharmacologique. Poux vivants à <span class=\"kw-chiffre\">J12</span> → mauvais effet lenticide\n      → <strong>refaire le produit initial</strong>.</div>","frequence":1},{"id":"171-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de gestion d’une épidémie de gale dans un établissement","contenu":"<p>Devant une épidémie de <span class=\"kw-etio\">gale</span> en collectivité (<strong><span class=\"kw-def\">EHPAD</span></strong> ++) :</p>\n      <ul>\n        <li><strong>Traiter tous <span class=\"kw-clinique\">les</span> membres de la collectivité en même temps</strong> — soignants, autres patients, visiteurs — <strong>même sans signe clinique</strong>.</li>\n        <li>Traitement de référence : <span class=\"kw-ttt\">ivermectine</span> per os.</li>\n        <li>Traiter l'<strong>environnement</strong> conjointement.</li>\n        <li>En <span class=\"kw-alerte\">hospitalisation</span> : <strong><span class=\"kw-def\">précautions complémentaires de type contact</span></strong>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Éviction de la collectivité (enfant)</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Durée d'éviction</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Gale</span> commune</td><td>Jusqu'à <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</td></tr>\n          <tr><td><span class=\"kw-etio\">Gale</span> profuse / hyperkératosique</td><td>Jusqu'à <strong>négativation de l'<span class=\"kw-bio\">examen parasitologique</span></strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Linge</strong> : lavage à <span class=\"kw-chiffre\">60 °C</span> en machine (cycle long) ou linge\n      enfermé dans un sac plastique <span class=\"kw-chiffre\">72 h</span>.</p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-def\">Isolement</span> immédiat :</strong> toute <span class=\"kw-etio\">gale</span> <span class=\"kw-alerte\">profuse</span> ou <span class=\"kw-alerte\">hyperkératosique</span> (contagiosité majeure) impose un <span class=\"kw-ttt\">isolement</span> avec <span class=\"kw-def\">précautions complémentaires de type contact</span>, idéalement en <span class=\"kw-alerte\">hospitalisation</span>.<br><strong>Répétition obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-ttt\">ivermectine</span> à répéter à <span class=\"kw-chiffre\">7-14 jours</span> (cycle <span class=\"kw-etio\">parasitaire</span>) ; traitement local renouvelé à <span class=\"kw-chiffre\">7-8 jours</span> ; pédiculose retraitée à <span class=\"kw-chiffre\">7-10 jours</span> (mauvais effet lenticide) — sans cette 2ᵉ prise, l’échec est quasi assuré.<br><strong><span class=\"kw-etio\">Décontamination</span> du linge :</strong> lavage <span class=\"kw-chiffre\">&gt; 60 °C</span> en machine (cycle long) ou linge enfermé en sac plastique <span class=\"kw-chiffre\">72 h</span> (gale) / <span class=\"kw-chiffre\">7 jours</span> (pou de corps).</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">gale</span> commune et pédiculoses se traitent en <span class=\"kw-ttt\">ambulatoire</span> (traitement local ou <span class=\"kw-ttt\">ivermectine</span> per os).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> / <span class=\"kw-def\">isolement</span> :</strong> gale <span class=\"kw-alerte\">profuse</span> ou <span class=\"kw-alerte\">hyperkératosique</span> — isoler le malade, <span class=\"kw-def\">précautions complémentaires de type contact</span>, idéalement en hospitalisation.<br><strong>Épidémie en collectivité (<span class=\"kw-def\">EHPAD</span> ++) :</strong> traiter TOUS <span class=\"kw-clinique\">les</span> membres en même temps (soignants, patients, visiteurs) même asymptomatiques, par <span class=\"kw-ttt\">ivermectine</span> per os, + traitement de l’environnement.<br><strong>Orientation <span class=\"kw-clinique\">IST</span> :</strong> gale du <span class=\"kw-etio\">pubis</span>, <span class=\"kw-etio\">phtiriase pubienne</span> ou gale après rapport à risque → <span class=\"kw-bio\">bilan d’IST</span> et <span class=\"kw-def\">dépistage</span>/traitement des partenaires.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Gale hyperkératosique</span> : contagiosité majeure par prolifération <span class=\"kw-etio\">parasitaire</span> intense → <span class=\"kw-def\">isolement</span> ; possible <span class=\"kw-alerte\">érythrodermie</span>, atteinte des <span class=\"kw-clinique\">ongles</span>, du visage et du cuir chevelu</li><li><span class=\"kw-alerte\">Gale profuse</span> : <span class=\"kw-clinique\">éruption</span> étendue y compris le <span class=\"kw-clinique\">dos</span> ; <span class=\"kw-def\">terrain</span> immunodéprimé (<span class=\"kw-etio\">VIH</span>), personne âgée alitée, diagnostic tardif ou <span class=\"kw-etio\">corticothérapie</span></li><li><span class=\"kw-alerte\">Surinfection / impétiginisation</span> des lésions de grattage — tout <span class=\"kw-clinique\">impétigo de l’adulte</span> doit faire rechercher une <span class=\"kw-etio\">gale</span> ; cause majeure de <span class=\"kw-alerte\">RAA</span> et de <span class=\"kw-alerte\">glomérulonéphrite post-streptococcique</span> dans <span class=\"kw-clinique\">les</span> pays en développement</li><li><span class=\"kw-alerte\">Pédiculose corporelle</span> : le pou de corps transmet la <span class=\"kw-etio\">fièvre des tranchées</span> (<span class=\"kw-etio\">Bartonella quintana</span>) responsable de <span class=\"kw-alerte\">septicémie</span> et d’<span class=\"kw-alerte\">endocardite</span>, le <span class=\"kw-etio\">typhus exanthématique</span> et la <span class=\"kw-etio\">fièvre récurrente cosmopolite</span></li><li><span class=\"kw-clinique\">Prurit</span> persistant <span class=\"kw-chiffre\">8-15 jours</span> après traitement, avec lésions évocatrices et/ou <span class=\"kw-bio\">examen parasitologique</span> positif = <span class=\"kw-alerte\">échec vrai</span> (rechute, résistance ou recontamination)</li></ul>","principes":"<p><span class=\"kw-etio\">Gale</span> : <span class=\"kw-ttt\">ivermectine</span> per os en 1ʳᵉ intention, traitements locaux en alternative ou en association ; traitement <strong>simultané des contacts</strong> et de l’environnement. Pédiculoses : traitement <span class=\"kw-ttt\">local</span> par <span class=\"kw-ttt\">diméticone</span>, 2ᵉ application systématique.</p><p><strong><span class=\"kw-etio\">Gale</span> — traitement général (1ʳᵉ intention)</strong></p><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os en <strong>prise unique</strong>, AMM chez l’adulte et l’enfant <span class=\"kw-chiffre\">&gt; 2 ans et &gt; 15 kg</span> — <span class=\"kw-ci\">CI &lt; 2 ans ou &lt; 15 kg</span></li><li>À <strong>répéter systématiquement à <span class=\"kw-chiffre\">7-14 jours</span></strong> (cycle <span class=\"kw-etio\">parasitaire</span> ; hors AMM mais indispensable pour éviter <span class=\"kw-clinique\">les</span> échecs)</li></ul><p><strong><span class=\"kw-etio\">Gale</span> — traitements locaux</strong></p><ul><li><span class=\"kw-ttt\">Benzoate de benzyle</span> émulsion <span class=\"kw-chiffre\">10 %</span> : du <strong>cuir chevelu aux orteils</strong>, dès <span class=\"kw-chiffre\">1 mois</span> — <span class=\"kw-ci\">CI &lt; 1 mois (toxicité neurologique)</span> ; pose <span class=\"kw-chiffre\">24 h</span> chez l’adulte, <span class=\"kw-chiffre\">6-12 h</span> entre <span class=\"kw-chiffre\">1 mois</span> et <span class=\"kw-chiffre\">2 ans</span> ; 2 applications à <span class=\"kw-chiffre\">8 jours</span></li><li><span class=\"kw-ttt\">Perméthrine</span> crème <span class=\"kw-chiffre\">5 %</span> : du <strong>cou aux orteils</strong>, dès <span class=\"kw-chiffre\">2 mois</span> ; pose <span class=\"kw-chiffre\">8-12 h</span> ; 2 applications à <span class=\"kw-chiffre\">7 jours</span></li><li><span class=\"kw-clinique\">Les</span> deux sont <strong>possibles chez la femme enceinte</strong>, <span class=\"kw-ci\">hors allaitement</span></li></ul><p><strong><span class=\"kw-etio\">Gale</span> — modalités d’application locale</strong></p><ul><li>Après une <span class=\"kw-ttt\">douche tiède au savon</span>, appliquer sur <strong>tout le corps</strong> zones génitales comprises (+ cuir chevelu et visage en cas de doute)</li><li><span class=\"kw-ci\">Ne pas se laver</span> pendant la durée de pose ; au retrait, douche puis <span class=\"kw-ttt\">émollient</span> (peau sèche et prurigineuse)</li></ul><p><strong><span class=\"kw-etio\">Gale</span> profuse / hyperkératosique</strong></p><ul><li><strong>Associer systématiquement</strong> le traitement <span class=\"kw-ttt\">local</span> + l’<span class=\"kw-ttt\">ivermectine</span> per os</li><li><span class=\"kw-ttt\">Isolement</span> du malade (<span class=\"kw-def\">précautions de type contact</span>), idéalement en <span class=\"kw-alerte\">hospitalisation</span> ; désinfection des lieux de vie</li></ul><p><strong>Sujets contacts (<span class=\"kw-etio\">gale</span>)</strong></p><ul><li>Traiter <strong>simultanément</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">contacts proches</span> : personnes vivant <strong>sous le même toit</strong> et <strong>partenaires sexuels</strong>, <strong>même asymptomatiques</strong></li><li>Même traitement que le cas index : <span class=\"kw-ttt\">traitement local</span> ou <span class=\"kw-ttt\">ivermectine</span> per os (à privilégier si le nombre de personnes est important, pour l’observance)</li></ul><p><strong>Environnement (<span class=\"kw-etio\">gale</span>)</strong></p><ul><li>Linge, draps et serviettes lavés à <span class=\"kw-chiffre\">&gt; 60 °C</span> en machine (cycle long) <strong>ou</strong> enfermés en sac plastique <span class=\"kw-chiffre\">72 h</span></li><li>Désinfection des lieux de vie uniquement si <span class=\"kw-etio\">gale</span> <span class=\"kw-alerte\">profuse</span> (inutile si gale commune)</li></ul><p><strong>Pédiculoses — principe général</strong></p><ul><li>Traitement <span class=\"kw-ttt\">local</span> par <span class=\"kw-ttt\">diméticone</span> ou <span class=\"kw-ttt\">oxyphtirine</span> (destruction <strong>mécanique</strong> du pou ; malathion et perméthrine ne sont plus disponibles)</li><li><strong>2ᵉ traitement systématique à <span class=\"kw-chiffre\">7-10 jours</span></strong> (mauvais effet lenticide) ; solutions, lotions et crèmes préférées aux <span class=\"kw-ci\">shampooings et poudres</span> (moins efficaces)</li><li><span class=\"kw-ci\">Pas de traitement présomptif</span> : seules <span class=\"kw-clinique\">les</span> pédiculoses actives se traitent</li></ul><p><strong>Pédiculose du cuir chevelu</strong></p><ul><li><span class=\"kw-ttt\">Diméticone</span> en solution/lotion appliquée <strong>raie par raie</strong>, pose <span class=\"kw-chiffre\">15 min à 1 h</span>, puis shampooing doux + rinçage + <strong>peignage</strong> ; refait à <span class=\"kw-chiffre\">7-10 jours</span></li><li>Échec d’un traitement local bien conduit : <span class=\"kw-ttt\">ivermectine</span> per os <span class=\"kw-chiffre\">400 µg/kg</span> en prise unique (<span class=\"kw-alerte\">hors AMM</span> ; &gt;<span class=\"kw-chiffre\"> 2 ans</span> et &gt;<span class=\"kw-chiffre\"> 15 kg</span> ; répétée à <span class=\"kw-chiffre\">7 jours</span>)</li><li>Désinfection des locaux <span class=\"kw-ci\">inutile</span> ; linge à <span class=\"kw-chiffre\">≥ 50 °C</span> ou aérosol insecticide ; traitement de la fratrie non indispensable, éviction scolaire <span class=\"kw-ci\">non systématique</span></li></ul><p><strong>Pédiculose corporelle</strong></p><ul><li><span class=\"kw-ttt\">Hygiène corporelle</span>, douche au savon, <strong>changement de vêtements</strong></li><li>Linge et literie lavés à <span class=\"kw-chiffre\">60 °C</span> en machine (cycle long) ou enfermés en sac plastique <span class=\"kw-chiffre\">7 jours</span></li></ul><p><strong>Phtiriase pubienne (<span class=\"kw-clinique\">IST</span>)</strong></p><ul><li><strong>Rechercher systématiquement <span class=\"kw-clinique\">les</span> autres <span class=\"kw-bio\">IST</span></strong> + dépister et traiter les partenaires sexuels</li><li><span class=\"kw-ttt\">Perméthrine</span> topique réitérée à <span class=\"kw-chiffre\">7 jours</span> ; le <span class=\"kw-ttt\">rasage</span> est le meilleur traitement</li></ul>","suivi":"<p><strong><span class=\"kw-etio\">Gale</span> — <span class=\"kw-clinique\">prurit</span> persistant <span class=\"kw-chiffre\">8-15 jours</span> (pas toujours un échec)</strong></p><ul><li>Évoquer : <span class=\"kw-etio\">eczéma de contact</span>, <span class=\"kw-etio\">irritation par le traitement</span>, <span class=\"kw-etio\">parasitophobie</span>, autres causes de <span class=\"kw-clinique\">prurit</span></li><li><strong>Nodules post-scabieux</strong> : réaction immuno-<span class=\"kw-etio\">allergique</span> sans sarcopte, persistent plusieurs semaines — <span class=\"kw-ci\">ne justifient pas un retraitement</span></li></ul><p><strong><span class=\"kw-etio\">Gale</span> — échec vrai</strong></p><ul><li>Lésions cliniques évocatrices et/ou <span class=\"kw-bio\">examen parasitologique</span> positif</li><li>Causes : <span class=\"kw-etio\">rechute</span> après traitement inapproprié, <span class=\"kw-alerte\">résistance</span> au traitement, <span class=\"kw-etio\">recontamination</span> après guérison</li></ul><p><strong>Pédiculose du cuir chevelu — examen de contrôle</strong></p><ul><li>Poux vivants à <span class=\"kw-chiffre\">J2</span> → <span class=\"kw-alerte\">résistance</span> probable → <strong>changer de classe pharmacologique</strong></li><li>Poux vivants à <span class=\"kw-chiffre\">J12</span> → mauvais effet lenticide → <strong>refaire le produit initial</strong></li></ul><p><strong>Pédiculoses — causes d’échec</strong></p><ul><li>Incompréhension, négligence, <span class=\"kw-etio\">coût</span> (aucune spécialité remboursée) ; <span class=\"kw-etio\">réinfestation</span> à partir de l’environnement</li><li>Durée/fréquence insuffisantes, <span class=\"kw-etio\">quantité de produit insuffisante</span>, forme galénique inappropriée, <span class=\"kw-alerte\">acquisition de résistance</span> des poux</li></ul><p><strong>Éviction de la collectivité</strong></p><ul><li><span class=\"kw-etio\">Gale</span> commune : jusqu’à <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</li><li><span class=\"kw-etio\">Gale</span> profuse / hyperkératosique : jusqu’à <strong>négativation de l’<span class=\"kw-bio\">examen parasitologique</span></strong></li><li>Pédiculose du cuir chevelu : éviction scolaire <span class=\"kw-ci\">non systématique</span> ; prévenir <span class=\"kw-clinique\">les</span> parents par écrit + examen de groupe</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf","label":"Collège Pilly — Voyageur (item 171, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ectoparasitose confirmée — Diagnostic clinique : gale (Sarcoptes scabiei) ou pédiculose (poux)","detail":"<h4>CAT — Traitement de la <span class=\"kw-etio\">gale</span> et des pédiculoses — Choix thérapeutique selon l’entité, la forme, le <span class=\"kw-def\">terrain</span> et le contexte</h4>","branches":[{"to":"q-gale","label":"Gale","color":"blue"},{"to":"q-pedic","label":"Pédiculose","color":"blue"}]},{"id":"q-gale","kind":"decision","label":"Forme et contexte de la gale ? — Commune (cas isolé) · profuse/hyperkératosique · épidémie en collectivité","branches":[{"to":"t-gale-profuse","label":"Profuse / hyperkératosique","color":"red"},{"to":"t-gale-collectivite","label":"Épidémie en collectivité (EHPAD)","color":"amber"},{"to":"q-gale-terrain","label":"Gale commune, cas isolé / familial","color":"green"}]},{"id":"t-gale-profuse","kind":"terminal","label":"Gale profuse ou hyperkératosique","color":"red","detail":"<h4>Traitement</h4><ul><li>Associer <strong>systématiquement</strong> le traitement <span class=\"kw-ttt\">local</span> (benzoate de benzyle ou perméthrine) + l’<span class=\"kw-ttt\">ivermectine</span> per os</li></ul><h4><span class=\"kw-def\">Isolement</span></h4><ul><li><span class=\"kw-ttt\">Isoler</span> le malade — <span class=\"kw-def\">précautions complémentaires de type contact</span>, idéalement en <span class=\"kw-alerte\">hospitalisation</span> (contagiosité majeure)</li></ul><h4>Environnement</h4><ul><li>Linge à <span class=\"kw-chiffre\">&gt; 60 °C</span> ou sac plastique <span class=\"kw-chiffre\">72 h</span> ; <strong>désinfection des lieux de vie</strong> (indiquée seulement dans <span class=\"kw-clinique\">les</span> formes profuses)</li></ul><h4>Éviction</h4><ul><li>Enfant : jusqu’à <strong>négativation de l’<span class=\"kw-bio\">examen parasitologique</span></strong></li></ul><h4>Conduite</h4><ul><li>Traiter simultanément <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">contacts proches</span></li><li>Rechercher une cause favorisante : <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">corticothérapie</span>, diagnostic tardif</li></ul>"},{"id":"t-gale-collectivite","kind":"terminal","label":"Épidémie de gale en collectivité","color":"amber","detail":"<h4>Conduite</h4><ul><li>Traiter <strong>TOUS <span class=\"kw-clinique\">les</span> membres de la collectivité en même temps</strong> — soignants, autres patients, visiteurs — <strong>même sans signe clinique</strong></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os (facilite l’observance d’un traitement de <span class=\"kw-clinique\">masse</span>)</li></ul><h4>Environnement</h4><ul><li>Traiter conjointement l’environnement (linge <span class=\"kw-chiffre\">&gt; 60 °C</span> ou sac <span class=\"kw-chiffre\">72 h</span>) ; en <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-def\">précautions de type contact</span></li></ul><h4>Éviction</h4><ul><li><span class=\"kw-etio\">Gale</span> commune : <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</li><li>Forme profuse / hyperkératosique : jusqu’à négativation de l’<span class=\"kw-bio\">examen parasitologique</span></li></ul>"},{"id":"q-gale-terrain","kind":"decision","label":"Terrain du patient ? — Conditionne le choix ivermectine PO vs traitement local","branches":[{"to":"t-gale-iverm","label":"Adulte ou enfant > 2 ans et > 15 kg","color":"green"},{"to":"t-gale-nourrisson","label":"Nourrisson / < 2 ans ou < 15 kg","color":"amber"},{"to":"t-gale-grossesse","label":"Femme enceinte","color":"amber"}]},{"id":"t-gale-iverm","kind":"terminal","label":"Ivermectine per os (1ʳᵉ intention)","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os en <strong>prise unique</strong>, <strong>répétée à <span class=\"kw-chiffre\">7-14 jours</span></strong> (cycle <span class=\"kw-etio\">parasitaire</span>)</li></ul><h4>Alternative</h4><ul><li>Traitement local : <span class=\"kw-ttt\">benzoate de benzyle</span> ou <span class=\"kw-ttt\">perméthrine</span></li></ul><h4>Contacts</h4><ul><li>Traiter <strong>simultanément</strong> <span class=\"kw-clinique\">les</span> contacts proches (<strong>même toit</strong> + partenaires sexuels), <strong>même asymptomatiques</strong></li></ul><h4>Environnement</h4><ul><li>Linge à <span class=\"kw-chiffre\">&gt; 60 °C</span> (cycle long) ou sac plastique <span class=\"kw-chiffre\">72 h</span></li></ul><h4>Éviction</h4><ul><li>Enfant : <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</li></ul>"},{"id":"t-gale-nourrisson","kind":"terminal","label":"Traitement local (ivermectine CI)","color":"amber","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-ci\">Ivermectine contre-indiquée &lt; 2 ans ou &lt; 15 kg</span> → traitement <strong>local</strong></li></ul><h4>Molécules</h4><ul><li><span class=\"kw-ttt\">Perméthrine</span> crème <span class=\"kw-chiffre\">5 %</span> dès <span class=\"kw-chiffre\">2 mois</span>, pose <span class=\"kw-chiffre\">8-12 h</span></li><li><span class=\"kw-ttt\">Benzoate de benzyle</span> dès <span class=\"kw-chiffre\">1 mois</span> (<span class=\"kw-ci\">CI &lt; 1 mois : toxicité neurologique</span>), pose réduite <span class=\"kw-chiffre\">6-12 h</span> entre <span class=\"kw-chiffre\">1 mois</span> et <span class=\"kw-chiffre\">2 ans</span></li></ul><h4>Traitement</h4><ul><li>2 applications espacées (<span class=\"kw-chiffre\">7 jours</span> perméthrine, <span class=\"kw-chiffre\">8 jours</span> benzoate)</li></ul><h4>Conduite</h4><ul><li>Traiter aussi <span class=\"kw-clinique\">les</span> contacts et l’environnement (linge <span class=\"kw-chiffre\">&gt; 60 °C</span> ou sac <span class=\"kw-chiffre\">72 h</span>)</li></ul>"},{"id":"t-gale-grossesse","kind":"terminal","label":"Femme enceinte — traitement local","color":"amber","detail":"<h4>Traitement</h4><ul><li>Traitement <strong>local possible</strong> : <span class=\"kw-ttt\">perméthrine</span> ou <span class=\"kw-ttt\">benzoate de benzyle</span>, <span class=\"kw-ci\">hors allaitement</span></li></ul><h4>Conduite</h4><ul><li>Traiter simultanément <span class=\"kw-clinique\">les</span> contacts proches et le linge / l’environnement</li></ul>"},{"id":"q-pedic","kind":"decision","label":"Localisation de la pédiculose ? — Cuir chevelu · corporelle · pubienne","branches":[{"to":"q-pedic-cuir","label":"Cuir chevelu","color":"green"},{"to":"t-pedic-corp","label":"Corporelle","color":"green"},{"to":"t-pedic-pubis","label":"Pubienne (phtiriase)","color":"amber"}]},{"id":"q-pedic-cuir","kind":"decision","label":"Diméticone, puis examen de contrôle — Évaluation des poux vivants à J2 et J12","branches":[{"to":"t-pedic-cuir-ok","label":"Traitement initial / contrôle négatif","color":"green"},{"to":"t-pedic-j2","label":"Poux vivants à J2","color":"amber"},{"to":"t-pedic-j12","label":"Poux vivants à J12","color":"amber"},{"to":"t-pedic-iverm","label":"Échec malgré traitement local bien conduit","color":"amber"}]},{"id":"t-pedic-cuir-ok","kind":"terminal","label":"Diméticone locale","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Diméticone</span> (ou oxyphtirine) en solution/lotion, appliquée <strong>raie par raie</strong>, pose <span class=\"kw-chiffre\">15 min à 1 h</span>, puis shampooing doux + rinçage + <strong>peignage</strong></li></ul><h4>Délai</h4><ul><li><strong>2ᵉ application systématique à <span class=\"kw-chiffre\">7-10 jours</span></strong> (mauvais effet lenticide)</li></ul><h4>Environnement</h4><ul><li>Désinfection des locaux <span class=\"kw-ci\">inutile</span> ; linge à <span class=\"kw-chiffre\">≥ 50 °C</span> ou aérosol insecticide</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ci\">Pas de traitement présomptif</span> : seules <span class=\"kw-clinique\">les</span> pédiculoses actives se traitent</li><li>Traitement de la fratrie non indispensable ; éviction scolaire <span class=\"kw-ci\">non systématique</span> ; prévenir <span class=\"kw-clinique\">les</span> parents par écrit + examen de groupe</li></ul>"},{"id":"t-pedic-j2","kind":"terminal","label":"Résistance probable","color":"amber","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Poux vivants à <span class=\"kw-chiffre\">J2</span> = <span class=\"kw-alerte\">résistance</span> probable des poux aux insecticides</li></ul><h4>Conduite</h4><ul><li><strong>Changer de classe pharmacologique</strong></li></ul>"},{"id":"t-pedic-j12","kind":"terminal","label":"Mauvais effet lenticide","color":"amber","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Poux vivants à <span class=\"kw-chiffre\">J12</span> = <strong>mauvais effet lenticide</strong> (éclosion d’œufs résiduels)</li></ul><h4>Conduite</h4><ul><li><strong>Refaire le produit initial</strong></li></ul>"},{"id":"t-pedic-iverm","kind":"terminal","label":"Ivermectine per os (hors AMM)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os <span class=\"kw-chiffre\">400 µg/kg</span> en prise unique, <strong>répétée à <span class=\"kw-chiffre\">7 jours</span></strong></li></ul><h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Sujets <span class=\"kw-chiffre\">&gt; 2 ans et &gt; 15 kg</span> ; <span class=\"kw-alerte\">hors AMM</span> dans cette indication — réservée au cuir chevelu (à ne pas utiliser dans <span class=\"kw-clinique\">les</span> autres pédiculoses)</li></ul>"},{"id":"t-pedic-corp","kind":"terminal","label":"Pédiculose corporelle","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hygiène corporelle</span>, douche au savon, <strong>changement de vêtements</strong></li></ul><h4>Environnement</h4><ul><li>Linge et literie lavés à <span class=\"kw-chiffre\">60 °C</span> (cycle long) ou enfermés en sac plastique <span class=\"kw-chiffre\">7 jours</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-etio\">Marqueur de précarité</span> ; le pou de corps est vecteur (<span class=\"kw-etio\">fièvre des tranchées</span>, <span class=\"kw-etio\">typhus</span>, <span class=\"kw-etio\">fièvre récurrente</span>) → évoquer ces infections selon le contexte</li></ul>"},{"id":"t-pedic-pubis","kind":"terminal","label":"Phtiriase pubienne (IST)","color":"amber","detail":"<h4>Conduite</h4><ul><li><strong>Phtiriase pubienne = <span class=\"kw-bio\">IST</span></strong> : rechercher systématiquement <span class=\"kw-clinique\">les</span> autres <span class=\"kw-clinique\">IST</span> + dépister et traiter les partenaires sexuels</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Perméthrine</span> topique suivie d’un savonnage, réitérée à <span class=\"kw-chiffre\">7 jours</span> ; le <span class=\"kw-ttt\">rasage</span> est le meilleur traitement</li></ul>"}]},"cards":[{"i":"1fcd3a9752d9","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quel est le traitement de première intention pour une pédiculose du cuir chevelu ?","a":"<p>Le traitement de première intention est l'application de <strong>diméticone</strong> (ou oxyphthirine) en solution ou lotion. Il s'applique <strong>raie par raie</strong>, nécessite une pose de <strong>15 minutes à 1 heure</strong>, suivi d'un shampoing doux, d'un rinçage et d'un peignage. Un <strong>deuxième traitement systématique à 7-10 jours</strong> est nécessaire en raison d'un mauvais effet lenticide des produits. Seules les pédiculoses actives sont traitées, il n'y a pas de traitement présomptif.</p>"},{"i":"677f3b07007e","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quelle est la prise en charge d'une gale profuse ou hyperkératosique ?","a":"<p>Une gale profuse ou hyperkératosique nécessite une association d'un <strong>traitement local et de l'ivermectine per os</strong>. Un <strong>isolement du malade</strong> (précautions de type contact), idéalement en hospitalisation, est indiqué. Une <strong>désinfection des lieux de vie</strong> est également nécessaire.</p>"},{"i":"88c3b90e1a52","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quels sont les traitements locaux de la gale, leurs galéniques, les âges minimaux et les zones d'application spécifiques ?","a":"<ul><li>Le <strong>benzoate de benzyle</strong> est une <strong>émulsion cutanée à 10 %</strong>, applicable dès l'âge de <strong>1 mois</strong> (contre-indiqué avant 1 mois en raison d'une toxicité neurologique). Il s'applique du <strong>cuir chevelu aux orteils</strong>. Le schéma est 2 applications à 8 jours d'intervalle.</li><li>La <strong>perméthrine</strong> est une <strong>crème à 5 %</strong>, applicable dès l'âge de <strong>2 mois</strong>. Elle s'applique du <strong>cou aux orteils</strong>. Le schéma est 2 applications à 7 jours d'intervalle.</li></ul>"},{"i":"9143fd3a2266","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quelle est la molécule de première intention et son schéma d'administration pour le traitement systémique de la gale non compliquée chez l'adulte et l'enfant de plus de 2 ans et 15 kg ?","a":"<p>La molécule de première intention est l'<strong>ivermectine</strong> per os. Elle est administrée en <strong>prise unique</strong>, avec une répétition à <strong>7-14 jours</strong> pour couvrir le cycle parasitaire. Elle est contre-indiquée chez l'enfant de moins de 2 ans ou pesant moins de 15 kg.</p>"},{"i":"c7e30f61ac39","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quelles sont les modalités d'application des traitements locaux de la gale et les mesures environnementales associées ?","a":"<p>Après une douche tiède au savon, le produit est appliqué sur <strong>tout le corps, y compris les zones génitales</strong>. Après l'application, des sous-vêtements propres sont enfilés et le patient ne doit pas se laver pendant le temps de pose (<strong>24 heures chez l'adulte</strong> pour le benzoate de benzyle, <strong>8-12 heures</strong> pour la perméthrine). Au retrait, une douche à l'eau et au savon suivie d'un émollient est recommandée. Les <strong>linges et la literie</strong> doivent être lavés à <strong>> 60°C</strong> ou enfermés dans un sac plastique pendant <strong>72 heures</strong>.</p>"},{"i":"e49b6c0eff0a","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Comment traiter une pédiculose corporelle et une phtiriase pubienne ?","a":"<ul><li>Pour la <strong>pédiculose corporelle</strong> : elle se traite principalement par <strong>hygiène corporelle</strong> (douche au savon), changement de vêtements et lavage du linge à <strong>60°C</strong> ou enfermement en sac plastique pendant <strong>7 jours</strong>.</li><li>Pour la <strong>phtiriase pubienne</strong> (morpions) : la <strong>perméthrine topique</strong> renouvelée à 7 jours est indiquée. Le <strong>rasage</strong> est le meilleur traitement. Il faut également rechercher les autres IST et traiter les partenaires sexuels.</li></ul>"},{"i":"519c4edd542a","n":171,"o":"171-12","u":"Prise en charge","t":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","q":"Quelle est la temporalité de traitement des sujets contacts en cas de gale, notamment par rapport au cas index ?","a":"<p>Le traitement des sujets contacts doit être réalisé de manière <strong>simultanée</strong> à celui du cas index. Il ne faut pas attendre l'apparition de symptômes chez les contacts pour initier le traitement.</p>"},{"i":"615731a1febe","n":171,"o":"171-12","u":"Prise en charge","t":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","q":"Quelles sont les modalités de traitement des sujets contacts en cas de gale, et que faut-il également traiter en parallèle ?","a":"<p>Les sujets contacts reçoivent le <strong>même traitement que le cas index</strong> :</p><ul><li>Un <strong>traitement local</strong> (peut suffire).</li><li>L'<strong>ivermectine per os</strong>, à privilégier pour l'observance lorsque le nombre de personnes à traiter est important.</li></ul><p>Il est indispensable de traiter également le <strong>linge</strong> et l'<strong>environnement</strong> de manière simultanée.</p>"},{"i":"99a9d267a936","n":171,"o":"171-12","u":"Prise en charge","t":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","q":"En cas de diagnostic de gale chez un patient, qui doit être considéré comme contact et recevoir un traitement préventif ?","a":"<p>Doivent être traités comme contacts les <strong>personnes vivant sous le même toit</strong> que le cas index et ses <strong>partenaires sexuels</strong>, qu'ils soient symptomatiques ou non.</p>"},{"i":"27e14cfec868","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quelles sont les localisations typiques des lésions non spécifiques de grattage dans le cadre d'une gale ?","a":"<ul><li><strong>Espaces interdigitaux</strong>.</li><li>Face antérieure des <strong>poignets et avant-bras</strong>, <strong>coudes</strong>, <strong>aisselles</strong>.</li><li>Région <strong>ombilicale</strong>, <strong>fesses</strong> et face interne des <strong>cuisses</strong>.</li><li><strong>Mamelons/aréoles</strong> chez la femme.</li><li><strong>Organes Génitaux Externes (OGE)</strong>, notamment la verge chez l'homme.</li></ul>"},{"i":"3f836379f234","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quels sont les signes évocateurs d'une pédiculose du cuir chevelu ?","a":"<p>Une pédiculose du cuir chevelu se manifeste par un <strong>prurit du cuir chevelu</strong>, diurne et nocturne, diffus ou à prédominance rétro-auriculaire, pouvant s'étendre à la nuque. On observe également des lésions de grattage, une éventuelle <strong>impétiginisation</strong> du cou et des <strong>adénopathies occipitales</strong>. Le diagnostic est confirmé par la présence de <strong>poux vivants</strong> ou de <strong>lentes vivantes</strong> (œufs brillants, non coulissants, collés au cheveu, surtout rétro-auriculaires).</p>"},{"i":"466b8571edd2","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quelles sont les lésions spécifiques de la gale, leur aspect et leur topographie ?","a":"<ul><li>Le <strong>sillon scabieux</strong> : lésion sinueuse de quelques millimètres, souvent aux espaces interdigitaux et face antérieure des poignets, correspondant au trajet de l'acarien femelle avec une <strong>éminence acarienne</strong> à une extrémité.</li><li>La <strong>vésicule perlée</strong> : petite élevure translucide sur base érythémateuse, typiquement aux espaces interdigitaux.</li><li>Le <strong>nodule scabieux</strong> : papulo-nodule rouge ou violacé, prurigineux, parfois excorié, surtout au niveau des régions génitales de l'homme.</li></ul>"},{"i":"60d308efc8cf","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Comment évoquer une pédiculose corporelle ?","a":"<p>La pédiculose corporelle se manifeste par un <strong>prurit intense</strong>, des excoriations et une éruption maculo-papuleuse prédominant au <strong>dos</strong>, au <strong>thorax</strong> et à la racine des membres. En cas d'infestation chronique, une <strong>leucomélanodermie</strong> peut apparaitre. Le diagnostic de certitude repose sur la présence de poux et de lentes, principalement sur les <strong>coutures des vêtements</strong>.</p>"},{"i":"921168ebb47c","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quels sont les signes cliniques évocateurs d'une phtiriase pubienne ?","a":"<p>La phtiriase pubienne est évoquée par un <strong>prurit pubien</strong> intense et des lésions de grattage du pubis et de l'hypogastre. Au diagnostic, on recherche la présence de <strong>lentes grisâtres</strong> et de <strong>poux immobiles</strong> à la base des poils pubiens.</p>"},{"i":"a8af850234b9","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quel est le piège classique à connaître concernant le diagnostic de la gale et des pédiculoses ?","a":"<ul><li>Il faut penser à la <strong>gale devant tout prurit</strong>, même pauci-lésionnel.</li><li>Tout <strong>impétigo de l'adulte</strong> doit faire rechercher une gale.</li><li>Tout <strong>impétigo de la nuque ou du cuir chevelu</strong> doit faire rechercher une pédiculose.</li></ul>"},{"i":"f82c8b95e439","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quel est le symptôme cardinal de la gale typique et ses caractéristiques principales ?","a":"<p>Le symptôme cardinal de la gale typique est un <strong>prurit diffus à recrudescence nocturne</strong>. Il épargne typiquement le <strong>visage</strong> et a souvent un caractère <strong>conjugal ou familial</strong>.</p>"},{"i":"1230359002d3","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Décrivez les caractéristiques des nodules scabieux et des vésicules perlées, deux lésions observées dans la gale.","a":"Les <strong>nodules scabieux</strong> sont des <strong>papulo-nodules rouges</strong> de <strong>5 à 10 mm</strong> de diamètre, localisés préférentiellement sur la <strong>verge</strong>, le scrotum, les aisselles ou les aréoles mammaires. Les <strong>vésicules perlées</strong> sont de petites <strong>élevures translucides</strong> reposant sur une <strong>base érythémateuse</strong>, fréquemment observées sur les poignets et les avant-bras."},{"i":"4f00da2f2d8d","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Décrivez les particularités cliniques de la gale hyperkératosique et son impact sur la contagiosité.","a":"La gale hyperkératosique se caractérise par des <strong>placards érythémato-squameux étendus</strong>, souvent généralisés et d'aspect pseudo-psoriasique ou eczématiforme. Elle présente une <strong>contagiosité majeure</strong> en raison du nombre très élevé de parasites présents sur la peau du patient."},{"i":"8f841dd2ffaf","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Comment se manifeste un sillon scabieux, lésion typique de la gale, et quelle est son origine ?","a":"Le sillon scabieux se manifeste comme une <strong>lésion sinueuse</strong> de quelques millimètres de long, le plus fréquemment dans un <strong>espace interdigital</strong>. Il correspond au tunnel creusé sous la couche cornée par l'<strong>acarien femelle</strong> (<em>Sarcoptes scabiei hominis</em>) pour pondre ses œufs."},{"i":"de2ef3784def","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Quelle est la description des lésions cutanées typiques de la gale et leur localisation préférentielle ?","a":"Les lésions cutanées typiques de la gale sont :\n<ul>\n<li>Le <strong>sillon scabieux</strong>, souvent trouvé dans les <strong>espaces interdigitaux</strong>.</li>\n<li>Les <strong>vésicules perlées</strong>, fréquentes sur les <strong>poignets</strong> et les <strong>avant-bras</strong>.</li>\n<li>Les <strong>nodules scabieux</strong>, classiquement observés sur la <strong>verge</strong> chez l'homme.</li>\n<li>La <strong>gale hyperkératosique</strong>, caractérisée par des <strong>placards érythémato-squameux étendus</strong>, souvent localisés sur les paumes, les plantes, ou le tronc.</li>\n</ul>"},{"i":"39591d070888","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Comment différencier une lente viable d'une lente non viable lors de l'examen clinique d'une pédiculose du cuir chevelu ?","a":"<p>Une lente est considérée comme non viable si elle est située à <strong>plus d'1 cm de l'émergence du cheveu</strong>, indiquant que le cheveu a déjà beaucoup poussé et que la lente est ancienne et probablement vide.</p>"},{"i":"a4d6660bbf57","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Quelle est la localisation prédominante des lentes observées lors d'une pédiculose du cuir chevelu ?","a":"<p>Les lentes sont observées avec une prédominance <strong>rétro-auriculaire</strong> (derrière les oreilles).</p>"},{"i":"b07660e2778d","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Quelle est la caractéristique morphologique des lentes (œufs de poux) de la pédiculose du cuir chevelu ?","a":"<p>Les lentes sont des <strong>œufs blanc-grisâtres</strong>, de forme allongée, <strong>collés fermement à la tige pilaire</strong>. Elles ne coulissent pas le long du cheveu, contrairement aux pellicules.</p>"},{"i":"e39df39c8ba1","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Quel élément permet de poser le diagnostic de certitude d'une pédiculose du cuir chevelu ?","a":"<p>Le diagnostic de certitude d'une pédiculose du cuir chevelu est posé par la découverte de <strong>poux adultes vivants</strong>, qui sont bruns, allongés et mobiles.</p>"},{"i":"022610f215df","n":171,"o":"171-8","u":"Examens complémentaires","t":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","q":"Dans quel contexte clinique, face à un diagnostic de gale ou de pédiculose, une recherche systématique d'autres Infections Sexuellement Transmissibles (IST) doit-elle être envisagée ?","a":"<p>Une recherche systématique d'autres IST doit être menée devant une <strong>gale du pubis</strong>, une <strong>phtiriase pubienne</strong> ou une <strong>gale survenue dans un contexte de rapports sexuels à risque</strong>.</p>"},{"i":"5cb7ebe04a40","n":171,"o":"171-8","u":"Examens complémentaires","t":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","q":"Comment doit être conduite la prise en charge des partenaires sexuels face au diagnostic d'une gale du pubis ou d'une phtiriase pubienne ?","a":"<p>Les partenaires sexuels doivent être systématiquement <strong>dépistés et traités</strong>.</p>"},{"i":"962b6451cb73","n":171,"o":"171-8","u":"Examens complémentaires","t":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","q":"Existe-t-il un bilan biologique spécifique pour le diagnostic de la gale ou de la pédiculose ?","a":"<p>Non, il n'existe <strong>pas de signe biologique spécifique</strong> ou de bilan biologique propre à la gale ou à la pédiculose. Le bilan est orienté vers la recherche d'<strong>IST associées</strong> si le contexte le justifie.</p>"}]};